<?php
require_once __DIR__.'/_init.php';log_activity($pdo,'admin_view_messages','Admin membuka daftar pesan kontak','contact_message');$rows=$pdo->query('SELECT * FROM ds_contact_messages ORDER BY created_at DESC')->fetchAll();admin_header('Pesan Kontak','messages');?>
<div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">INBOX</span><h2>Pesan dari pengunjung</h2></div><span class="muted"><?=count($rows)?> pesan</span></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Pengirim</th><th>Subjek</th><th>Pesan</th><th>Waktu</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><small class="table-sub"><?=e($r['email'])?></small></td><td><?=e($r['subject'])?></td><td class="message-cell"><?=nl2br(e($r['message']))?></td><td><?=e(date('d/m/Y H:i',strtotime($r['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></div><?php admin_footer();?>
